y\": \"sha256:dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd\",\n            \"callId\": \"fixture-call-001\",\n            \"callType\": \"audio\",\n            \"callerName\": \"\u5951\u7ea6\u6765\u7535\",\n            \"sourceLabel\": \"\u5951\u7ea6\u4f1a\u8bdd\",\n            \"trustRelation\": \"known\",\n            \"expiresAt\": \"2030-01-01T00:00:00Z\"\n          },\n          \"status\": \"accepted\"\n        }\n      ],\n      \"providerPolicy\": {\n        \"sms_otp.send\": {\n          \"primaryProvider\": \"mock_sms\",\n          \"backupProvider\": \"mock_sms\",\n          \"maxAttempts\": 3\n        },\n        \"push_delivery.send\": {\n          \"primaryProvider\": \"alpha_fake\",\n          \"maxAttempts\": 5\n        }\n      }\n    }\n  },\n  \"scenarios\": [\n    {\n      \"id\": \"integration_location_poi_basic\",\n      \"title\": \"\u53d1\u5e03\u4f4d\u7f6e\u9009\u62e9\u5951\u7ea6\u79cd\u5b50\",\n      \"type\": \"location_poi\",\n      \"domainId\": \"integration\",\n      \"seedRefs\": [\n        \"location_poi_core\"\n      ],\n      \"uiExpectations\": {\n        \"poiIds\": [\n          \"fixture_poi_west_lake\",\n          \"fixture_poi_coffee\"\n        ],\n        \"textFragments\": [\n          \"\u676d\u5dde\u897f\u6e56\",\n          \"\u5951\u7ea6\u5496\u5561\u9986\"\n        ]\n      },\n      \"remoteExpectations\": {\n        \"poiIds\": [\n          \"fixture_poi_west_lake\",\n          \"fixture_poi_coffee\"\n        ]\n      },\n      \"environments\": {\n        \"alpha\": {\n          \"enabled\": true,\n          \"repository\": \"mock\"\n        },\n        \"beta\": {\n          \"enabled\": true,\n          \"repository\": \"remote\",\n          \"requiresSeedReset\": true\n        },\n        \"gamma\": {\n          \"enabled\": true,\n          \"repository\": \"remote\",\n          \"requiresSeedReset\": true\n        }\n      }\n    },\n    {\n      \"id\": \"integration_external_interaction_sms_otp_async\",\n      \"title\": \"\u77ed\u4fe1\u9a8c\u8bc1\u7801\u53ef\u9760\u5f02\u6b65\u53d1\u9001\u5951\u7ea6\u79cd\u5b50\",\n      \"type\": \"external_interaction\",\n      \"domainId\": \"integration\",\n      \"seedRefs\": [\n        \"external_interaction_core\"\n      ],\n      \"remoteExpectations\": {\n        \"requestIds\": [\n          \"fixture_ext_sms_otp_001\"\n        ],\n        \"operations\": [\n          \"sms_otp.send\"\n        ],\n        \"acceptedStatus\": 202,\n        \"callbackEvents\": [\n          \"SmsOtpDeliverySucceeded\"\n        ]\n      },\n      \"environments\": {\n        \"alpha\": {\n          \"enabled\": true,\n          \"repository\": \"mock\"\n        },\n        \"beta\": {\n          \"enabled\": true,\n          \"repository\": \"remote\",\n          \"requiresSeedReset\": true\n        },\n        \"gamma\": {\n          \"enabled\": true,\n          \"repository\": \"remote\",\n          \"requiresSeedReset\": true\n        }\n      }\n    },\n    {\n      \"id\": \"integration_push_delivery_async\",\n      \"title\": \"\u624b\u673a\u63a8\u9001\u53ef\u9760\u5f02\u6b65\u53d1\u9001\u5951\u7ea6\u79cd\u5b50\",\n      \"type\": \"push_delivery\",\n      \"domainId\": \"integration\",\n      \"seedRefs\": [\n        \"external_interaction_core\"\n      ],\n      \"remoteExpectations\": {\n        \"requestIds\": [\n          \"fixture_ext_push_001\"\n        ],\n        \"operations\": [\n          \"push_delivery.send\"\n        ],\n        \"acceptedStatus\": 202,\n        \"callbackEvents\": [\n          \"PushDeliverySucceeded\"\n        ]\n      },\n      \"environments\": {\n        \"alpha\": {\n          \"enabled\": true,\n          \"repository\": \"mock\"\n        },\n        \"beta\": {\n          \"enabled\": true,\n          \"repository\": \"remote\",\n          \"requiresSeedReset\": true\n        },\n        \"gamma\": {\n          \"enabled\": true,\n          \"repository\": \"remote\",\n          \"req